export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * Adds whole calendar months, preserving the day of month where the target
 * month has one, and otherwise clamping to that month's last day — 31
 * January + 1 month is 28 February, and 28 February + 1 month (carrying the
 * clamp forward) is 28 March, never 31 March. Billing periods are built by
 * chaining this from the previous period's (possibly clamped) end.
 */
export function addMonths(value: IsoTimestamp, months: number): IsoTimestamp {
  const date = parseIso(value);
  const totalMonths = date.getUTCMonth() + months;
  const targetYear = date.getUTCFullYear() + Math.floor(totalMonths / 12);
  const targetMonth = ((totalMonths % 12) + 12) % 12;
  const lastDayOfTargetMonth = new Date(
    Date.UTC(targetYear, targetMonth + 1, 0),
  ).getUTCDate();
  const day = Math.min(date.getUTCDate(), lastDayOfTargetMonth);

  return toIsoTimestamp(
    new Date(
      Date.UTC(
        targetYear,
        targetMonth,
        day,
        date.getUTCHours(),
        date.getUTCMinutes(),
        date.getUTCSeconds(),
        date.getUTCMilliseconds(),
      ),
    ),
  );
}

/** Whole days spanned by a period, rounded, never less than one. */
export function daysInPeriod(start: IsoTimestamp, end: IsoTimestamp): number {
  const spanMs = parseIso(end).getTime() - parseIso(start).getTime();
  return Math.max(1, Math.round(spanMs / DAY_MS));
}

/**
 * Whole-or-started days remaining from `reference` to a period's end — 14
 * days and 22 hours left counts as 15. Zero once the end has been reached.
 */
export function daysLeftInPeriod(
  end: IsoTimestamp,
  reference: Date,
): number {
  const remainingMs = parseIso(end).getTime() - reference.getTime();
  if (remainingMs <= 0) return 0;
  return Math.ceil(remainingMs / DAY_MS);
}

