/**
 * A mid-period plan change that keeps the current period and status as
 * dictated by the caller — unlike `updateSubscriptionPlan`, it does not force
 * the subscription active, so choosing a plan mid-trial can stay `trialing`.
 */
export async function changeSubscriptionPlan(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
  status: SubscriptionStatus,
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({ plan, interval, status, updatedAt: stamp })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Leaving the free plan for a paid one starts a fresh, fully-charged period. */
export async function setPlanWithFreshPeriod(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({
      plan,
      interval,
      status: "active",
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
      updatedAt: stamp,
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Advances the period only, for the renewal job; plan/status/seats untouched. */
export async function setPeriod(
  orgId: OrgId,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
      updatedAt: stamp,
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
