/** 1 for a monthly period, 12 for an annual one. */
export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/** The full, unprorated charge for one period of a plan at a given seat count. */
export function fullPeriodChargeCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly *
    seats *
    monthsInInterval(interval)
  );
}

/**
 * Scales a full-period charge down to the days left in the current period,
 * rounded down to whole cents. Zero once the period has ended.
 */
export function prorateCents(
  fullChargeCents: number,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
  reference: Date,
): number {
  const daysLeft = daysLeftInPeriod(periodEnd, reference);
  if (daysLeft <= 0) return 0;

  const totalDays = daysInPeriod(periodStart, periodEnd);
  return Math.floor((fullChargeCents * daysLeft) / totalDays);
}

/**
 * Writes one invoice row and announces it. A non-positive charge produces no
 * invoice at all — proration can legitimately land on zero.
 */
export async function issueInvoice(
  orgId: OrgId,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
  amountCents: number,
  actorId: UserId | null,
): Promise<Invoice | null> {
  if (amountCents <= 0) return null;

  const number = await nextInvoiceNumber(orgId);
  const invoice = await invoiceRepo.insertInvoice(orgId, {
    orgId,
    number,
    amountCents,
    currency: "usd",
    periodStart,
    periodEnd,
    paidAt: null,
  });

  await emit("billing.invoice_issued", {
    orgId,
    actorId,
    occurredAt: toIsoTimestamp(new Date()),
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });

  return invoice;
}

/** Unique within the workspace; a plain running count is enough here. */
async function nextInvoiceNumber(orgId: OrgId): Promise<string> {
  const existing = await invoiceRepo.listInvoices(orgId);
  return `INV-${(existing.length + 1).toString().padStart(5, "0")}`;
}

/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 *
 * Mid-trial, a plan choice is free and keeps the trial period. Leaving the
 * free plan for a paid one starts a fresh, fully-charged period. Otherwise
 * the current period is unchanged, and an active move between two paid plans
 * is prorated for the price difference; a downgrade, an unchanged plan, or a
 * move to the free plan charges nothing.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const currentPlan = subscription.plan;

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const now = new Date();
  let updated: Subscription;

  if (subscription.status === "trialing") {
    updated = await subscriptionRepo.changeSubscriptionPlan(
      input.orgId,
      input.plan,
      input.interval,
      "trialing",
    );
  } else if (currentPlan === "free" && input.plan !== "free") {
    const periodStart = toIsoTimestamp(now);
    const periodEnd = addMonths(periodStart, monthsInInterval(input.interval));

    updated = await subscriptionRepo.setPlanWithFreshPeriod(
      input.orgId,
      input.plan,
      input.interval,
      periodStart,
      periodEnd,
    );

    const amount = fullPeriodChargeCents(
      input.plan,
      subscription.seats,
      input.interval,
    );
    await issueInvoice(input.orgId, periodStart, periodEnd, amount, actor.userId);
  } else {
    if (
      subscription.status === "active" &&
      currentPlan !== "free" &&
      input.plan !== "free"
    ) {
      const priceDiff =
        getPlanLimits(input.plan).priceCentsPerSeatMonthly -
        getPlanLimits(currentPlan).priceCentsPerSeatMonthly;

      if (priceDiff > 0) {
        const months = monthsInInterval(subscription.interval);
        const fullCharge = priceDiff * subscription.seats * months;
        const amount = prorateCents(
          fullCharge,
          subscription.currentPeriodStart,
          subscription.currentPeriodEnd,
          now,
        );
        await issueInvoice(
          input.orgId,
          subscription.currentPeriodStart,
          subscription.currentPeriodEnd,
          amount,
          actor.userId,
        );
      }
    }

    updated = await subscriptionRepo.changeSubscriptionPlan(
      input.orgId,
      input.plan,
      input.interval,
      "active",
    );
  }

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return updated;
}

/**
 * Adding seats to a paid, active subscription is charged for the seats added,
 * prorated over the days left in the current period. Removing seats, or any
 * seat change on the free plan or during a trial, charges nothing.
 */
export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  if (input.seats > getLimit(subscription.plan, "seats")) {
    throw new Error(
      `Plan ${subscription.plan} tops out at ${getLimit(subscription.plan, "seats")} seats`,
    );
  }

  const seatsAdded = input.seats - subscription.seats;

  if (
    seatsAdded > 0 &&
    subscription.plan !== "free" &&
    subscription.status === "active"
  ) {
    const months = monthsInInterval(subscription.interval);
    const fullCharge =
      getPlanLimits(subscription.plan).priceCentsPerSeatMonthly *
      seatsAdded *
      months;
    const amount = prorateCents(
      fullCharge,
      subscription.currentPeriodStart,
      subscription.currentPeriodEnd,
      new Date(),
    );
    await issueInvoice(
      input.orgId,
      subscription.currentPeriodStart,
      subscription.currentPeriodEnd,
      amount,
      actor.userId,
    );
  }

  return subscriptionRepo.updateSeatCount(input.orgId, input.seats);
}

