 * subscriptions roll their period forward one interval at a time until the
 * new period end lies after `now`, invoicing each paid period along the way.
 * A `canceled` subscription whose cancellation date has arrived moves to the
 * free plan as of that date. `trialing` and `past_due` subscriptions are left
 * for the trial-expiry job.
 *
 * Replay-safe: once a subscription's period end lies after `now` (or its
 * cancellation has already taken effect), running this again at the same
 * instant finds nothing left to do.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listSubscriptionsForBillingRenewal();

    for (const subscription of subscriptions) {
      try {
        if (subscription.status === "active") {
          await renewActiveSubscription(subscription, now);
        } else if (subscription.status === "canceled") {
          await endCancellationIfDue(subscription, now);
        } else {
          continue;
        }

        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed for workspace", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/** Rolls the period forward one interval per elapsed billing cycle, invoicing each paid one. */
async function renewActiveSubscription(
  subscription: Subscription,
  now: Date,
): Promise<void> {
  let periodStart = subscription.currentPeriodStart;
  let periodEnd = subscription.currentPeriodEnd;
  const months = monthsInInterval(subscription.interval);
  let renewed = false;

  for (
    let iteration = 0;
    new Date(periodEnd).getTime() <= now.getTime() &&
    iteration < MAX_PERIODS_PER_RUN;
    iteration += 1
  ) {
    const newStart = periodEnd;
    const newEnd = addMonths(newStart, months);

    if (subscription.plan !== "free") {
      const amount = fullPeriodChargeCents(
        subscription.plan,
        subscription.seats,
        subscription.interval,
      );
      await issueInvoice(subscription.orgId, newStart, newEnd, amount, null);
    }

    periodStart = newStart;
    periodEnd = newEnd;
    renewed = true;
  }

  if (renewed) {
    await subscriptionRepo.setPeriod(subscription.orgId, periodStart, periodEnd);
  }
}

/** Ends a cancellation once its date has arrived, moving the workspace to a fresh free period. */
async function endCancellationIfDue(
  subscription: Subscription,
  now: Date,
): Promise<void> {
  if (subscription.cancelAt === null) return;
  if (new Date(subscription.cancelAt).getTime() > now.getTime()) return;

  let periodStart = subscription.cancelAt;
  let periodEnd = addMonths(periodStart, 1);

  for (
    let iteration = 0;
    new Date(periodEnd).getTime() <= now.getTime() &&
    iteration < MAX_PERIODS_PER_RUN;
    iteration += 1
  ) {
    periodStart = periodEnd;
    periodEnd = addMonths(periodStart, 1);
  }

  const fromPlan = subscription.plan;
  await subscriptionRepo.endCancellation(subscription.orgId, periodStart, periodEnd);

  await emit("billing.plan_changed", {
    orgId: subscription.orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(now),
    from: fromPlan,
    to: "free",
  });
}

