import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { createTenant, useTemporaryDatabase } from "./tests/server/_support/fixtures";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as billingService from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("sanity: billing renewal", () => {
  it("renews three elapsed monthly periods and invoices each", async () => {
    const tenant = await createTenant("sanity-renew", "starter");
    // force subscription active & period far behind
    await subscriptionRepo.changeSubscriptionPlan(tenant.org.id, "starter", "monthly", "active");
    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    await subscriptionRepo.setPeriod(
      tenant.org.id,
      toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z")),
      toIsoTimestamp(new Date("2026-02-01T00:00:00.000Z")),
    );

    const now = new Date("2026-04-15T00:00:00.000Z");
    const result = await runBillingRenewalJob(now);
    console.log("result", result);

    const updated = await subscriptionRepo.findSubscription(tenant.org.id);
    console.log("period", updated?.currentPeriodStart, updated?.currentPeriodEnd);

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    console.log("invoices", invoices.map(i => ({ number: i.number, amount: i.amountCents, start: i.periodStart, end: i.periodEnd })));

    expect(invoices.length).toBe(3);
    expect(updated?.currentPeriodEnd > toIsoTimestamp(now)).toBe(true);

    // replay safety
    const result2 = await runBillingRenewalJob(now);
    const invoices2 = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices2.length).toBe(3);
  });

  it("prorates seat addition", async () => {
    const tenant = await createTenant("sanity-seats", "starter");
    await subscriptionRepo.changeSubscriptionPlan(tenant.org.id, "starter", "monthly", "active");
    await subscriptionRepo.setPeriod(
      tenant.org.id,
      toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z")),
      toIsoTimestamp(new Date("2026-02-01T00:00:00.000Z")),
    );
    // "now" inside updateSeats is real Date.now(); instead let's just check logic directly with current period far future
    const far = await subscriptionRepo.setPeriod(
      tenant.org.id,
      toIsoTimestamp(new Date()),
      toIsoTimestamp(new Date(Date.now() + 30*24*60*60*1000)),
    );
    const updated = await billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: tenant.userIds ? 2 : 2 } as any);
    console.log("seats updated", updated);
    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    console.log("seat invoices", invoices);
    expect(invoices.length).toBe(1);
  });
});
